<?php declare(strict_types=1); require __DIR__.'/auth.php'; if(is_file(ADMIN_FILE)){header('Location: login.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check((string)($_POST['csrf']??'')))$err='Sicherheitsprüfung fehlgeschlagen.';else{$email=trim((string)($_POST['email']??''));$pw=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Bitte eine gültige E-Mail eingeben.';elseif(strlen($pw)<12)$err='Das Passwort muss mindestens 12 Zeichen haben.';else{$payload=json_encode(['email'=>$email,'password_hash'=>password_hash($pw,PASSWORD_DEFAULT)],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);if(file_put_contents(ADMIN_FILE,$payload,LOCK_EX)===false)$err='Der Zugang konnte nicht gespeichert werden. Prüfe die Schreibrechte des Ordners data.';else{chmod(ADMIN_FILE,0600);header('Location: login.php?setup=1');exit;}}}}?><!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Admin einrichten</title><link rel="stylesheet" href="admin.css?v=2"><main class="box"><h1>Admin einrichten</h1><p>Beim ersten Aufruf legst du deine eigene Admin-E-Mail und dein Passwort fest.</p><?php if($err):?><p class="err"><?=htmlspecialchars($err,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf(),ENT_QUOTES,'UTF-8')?>"><label>E-Mail</label><input type="email" name="email" autocomplete="username" required><label>Passwort</label><input type="password" name="password" minlength="12" autocomplete="new-password" required><button>Admin-Zugang erstellen</button></form></main></html>
